const response = $input.item.json;
const content = response.choices?.[0]?.message?.content || '{}';

let queries = { people: '', company: '' };
try {
  const clean = content.trim().replace(/^```json?\s*/i, '').replace(/\s*```$/, '');
  const parsed = JSON.parse(clean);
  queries.people = String(parsed.people || '').trim();
  queries.company = String(parsed.company || '').trim();
} catch (e) {
  const pm = content.match(/"people"\s*:\s*"((?:[^"\\]|\\.)+)"/);
  const cm = content.match(/"company"\s*:\s*"((?:[^"\\]|\\.)+)"/);
  if (pm) queries.people = pm[1];
  if (cm) queries.company = cm[1];
}

return [{ json: { queries } }];
